DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261103140738_NeighborhoodDeliveryMapping') THEN
    CREATE TABLE "AddressProvinces" (
        "Id" integer NOT NULL,
        "Name" character varying(120) NOT NULL,
        CONSTRAINT "PK_AddressProvinces" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261103140738_NeighborhoodDeliveryMapping') THEN
    CREATE TABLE "AddressDistricts" (
        "Id" integer NOT NULL,
        "Name" character varying(120) NOT NULL,
        "ProvinceId" integer NOT NULL,
        CONSTRAINT "PK_AddressDistricts" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AddressDistricts_AddressProvinces_ProvinceId" FOREIGN KEY ("ProvinceId") REFERENCES "AddressProvinces" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261103140738_NeighborhoodDeliveryMapping') THEN
    CREATE TABLE "AddressNeighborhoods" (
        "Id" integer NOT NULL,
        "Name" character varying(160) NOT NULL,
        "LocalityName" character varying(120),
        "DistrictId" integer NOT NULL,
        "DeliveryRegionId" integer,
        CONSTRAINT "PK_AddressNeighborhoods" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AddressNeighborhoods_AddressDistricts_DistrictId" FOREIGN KEY ("DistrictId") REFERENCES "AddressDistricts" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_AddressNeighborhoods_DeliveryRegions_DeliveryRegionId" FOREIGN KEY ("DeliveryRegionId") REFERENCES "DeliveryRegions" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
